package org.evox.spen.compat;
import android.content.*;import android.os.*;import android.provider.Settings;import android.database.ContentObserver;import android.view.*;import android.graphics.Point;import android.util.Log;import java.io.*;import java.util.regex.*;
/** Own-package hardware events drive Samsung's existing controller and charging UI. */
public final class NativePenInput {
 private static boolean started;private static final Handler main=new Handler(Looper.getMainLooper());
 private static final String UI="com.samsung.android.service.aircommand.svc.aircommandui.AirCommandUiService";
 private static void service(Context c,Intent i){try{c.startService(i);}catch(IllegalStateException denied){new Thread(()->{try{String command="am startservice -n "+c.getPackageName()+"/"+i.getComponent().getClassName();Bundle b=i.getExtras();if(b!=null)for(String k:b.keySet()){Object v=b.get(k);if(v instanceof Boolean)command+=" --ez "+k+" "+v;else if(v instanceof Integer)command+=" --ei "+k+" "+v;else if(v instanceof String)command+=" --es "+k+" "+RootAccess.quote((String)v);}String result=RootAccess.run(command);if(result.contains("Error"))Log.e("AirCommandPort","Native event service refused: "+result.trim());}catch(Exception e){Log.e("AirCommandPort","Native event service failed",e);}},"AirCommand-event-start").start();}}
 public static void insertion(Context c,boolean docked,boolean initial){NativeFloatingPolicy.insertion(c,docked);main.post(()->{Intent i=new Intent().setClassName(c.getPackageName(),UI).putExtra("action","com.samsung.pen.INSERT").putExtra("penInsert",docked).putExtra("isBoot",initial);service(c,i);Log.i("AirCommandPort","Original UI insertion dispatched docked="+docked+" initial="+initial);});}
 private static void cursor(Context c){try{int value=SystemSettings.getInt(c.getContentResolver(),"pen_hovering_pointer",1);Settings.Secure.putInt(c.getContentResolver(),"stylus_pointer_icon_enabled",value==0?0:1);Log.i("AirCommandPort","Original pointer setting applied to Android input: "+(value!=0));}catch(Exception e){Log.e("AirCommandPort","Pointer setting could not be applied",e);}}
 public static synchronized void start(Context c){if(started)return;started=true;RuntimeContext.init(c);final Context app=c.getApplicationContext();main.post(()->{cursor(app);app.getContentResolver().registerContentObserver(SystemSettings.getUriFor("pen_hovering_pointer"),false,new ContentObserver(main){public void onChange(boolean self){cursor(app);}});});Thread worker=new Thread(()->read(app),"AirCommand-native-pen-input");worker.setDaemon(true);worker.start();}
 private static void read(Context c){java.lang.Process process=null;try{
  process=new ProcessBuilder("su","-c","echo SPEN_INPUT_READY; exec getevent -lt").redirectErrorStream(true).start();
  try(BufferedReader in=new BufferedReader(new InputStreamReader(process.getInputStream()))){Pattern re=Pattern.compile("EV_(ABS|KEY|SYN)\\s+(\\w+)\\s+(\\w+)");int x=-1,y=-1;boolean touch=false,side=false,hover=false;PenTapSequence tap=new PenTapSequence();String row;
   while((row=in.readLine())!=null){if(row.equals("SPEN_INPUT_READY")){Settings.Secure.putInt(c.getContentResolver(),"evox_aircommand_native_pen_input",1);Log.i("AirCommandPort","Native pen menu input active in original package");continue;}Matcher m=re.matcher(row);if(!m.find()){if(row.contains("denied")||row.contains("not found"))throw new IOException("Pen input unavailable");continue;}String kind=m.group(1),key=m.group(2),word=m.group(3);if(row.contains("/dev/input/event3:")){if(key.equals("ABS_MT_TRACKING_ID")&&!word.equals("ffffffff"))NativeFloatingPolicy.fingerDown(c);continue;}if(!row.contains("/dev/input/event5:"))continue;int v=word.equals("DOWN")?1:word.equals("UP")?0:(int)Long.parseLong(word,16);
    if(kind.equals("ABS")){if(key.equals("ABS_X"))x=v;if(key.equals("ABS_Y"))y=v;}else if(kind.equals("KEY")){if(key.equals("BTN_DIGI")||key.equals("BTN_TOOL_PEN")||key.equals("BTN_TOOL_RUBBER"))hover=v!=0;if(key.equals("BTN_TOUCH"))touch=v!=0;if(key.equals("BTN_STYLUS"))side=v!=0;}else if(key.equals("SYN_DROPPED")){touch=side=hover=false;NativePenTapShield.reset();NativePenArbitration.frame(false,false);tap.reset();NativeHoverCursor.hide();}else if(key.equals("SYN_REPORT")){NativePenTapShield.frame(c,hover||touch,touch,side);NativePenArbitration.frame(hover||touch,side);NativeHoverCursor.frame(c,hover,touch,x,y);NativeFloatingPolicy.penFrame(c,touch);boolean enabled=SystemSettings.getInt(c.getContentResolver(),"air_cmd_with_pen_button",1)!=0;int[] point=tap.frame(touch,side,x,y,SystemClock.uptimeMillis(),enabled);if(point!=null){Display d=((WindowManager)c.getSystemService(Context.WINDOW_SERVICE)).getDefaultDisplay();Point size=new Point();d.getRealSize(size);float u=Math.max(0,Math.min(1,point[0]/16714f)),v2=Math.max(0,Math.min(1,point[1]/26712f)),sx=u,sy=v2;switch(d.getRotation()){case 1:sx=v2;sy=1-u;break;case 2:sx=1-u;sy=1-v2;break;case 3:sx=1-v2;sy=u;break;}final int px=Math.round(sx*(size.x-1)),py=Math.round(sy*(size.y-1));main.postDelayed(()->{service(c,new Intent().setClassName(c.getPackageName(),UI).putExtra("native_pen_tap",true).putExtra("cause","button_pressed").putExtra("button_press_x",px).putExtra("button_press_y",py));Log.i("AirCommandPort","Original menu opened after pen release at "+px+","+py);},120);}}
   }
  }
 }catch(Exception e){Log.e("AirCommandPort","Native pen input stopped",e);}finally{NativePenTapShield.reset();NativePenArbitration.frame(false,false);NativeHoverCursor.hide();if(process!=null)process.destroy();try{Settings.Secure.putInt(c.getContentResolver(),"evox_aircommand_native_pen_input",0);}catch(Exception ignored){}synchronized(NativePenInput.class){started=false;}}}
}
